// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 _number1, uint64 _sequenceNumber1, uint64 _number2, uint64 _sequenceNumber2) public {
        vm.assume(_sequenceNumber1 != _sequenceNumber2);
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(_number1, 0, 0, bytes32(0), _sequenceNumber1, bytes32(0), 0, 0);
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(_number2, 0, 0, bytes32(0), _sequenceNumber2, bytes32(0), 0, 0);
        assertEq(c.number(), _number2);
    }
}
